func TestParseHookEvent_SubagentStart(t *testing.T) {
	t.Parallel()

	ag := &FactoryAIDroidAgent{}
	input := `{"session_id": "sess-4", "transcript_path": "/tmp/t.jsonl", "tool_use_id": "tu-123", "tool_input": {"prompt": "do something"}}`

